_debug = True  # False to eliminate debug printing from callback functions.
location = tkEditorDemo1._location
programName = "PyEditor"
version = "0.1.0"


def main(*args):
    """Main entry point for the application."""
    global root
    root = tk.Tk()
    root.protocol("WM_DELETE_WINDOW", root.destroy)
    # Creates a toplevel widget.
    global _top1, _w1
    _top1 = root
    _w1 = tkEditorDemo1.Toplevel1(_top1)
    startup()
    root.mainloop()


def startup():
    _w1.frameAbout.lower()
    global ed1
    pyed = tkEditor1.PyEditor
    ed1 = pyed(_w1.frameEd1)
    # ed1.clear_editor()
    # ed1.load_file("pyScrolledText15.py")
    _top1.title(f"{programName} - {version}")
    libVer = ed1.get_version()
    libLic = ed1.get_licence()
    print(f"{libVer=}")
    print(f"{libLic=}")
    global current_filename
    current_filename = ""


